mapper.select:
select aou.*,km.name as kfName,mu.nickname from aoc_user aou
left join kf_manage km on km.id = aou.kf_id
left join member_user mu on mu.id = aou.bind_user_id


        and (
            aou.friend_wechat_id like concat('%', #{reqVo.friendWechatId}, '%')
            or aou.friend_nickname like concat('%', #{reqVo.friendWechatId}, '%')
            or aou.friend_alias like concat('%', #{reqVo.friendWechatId}, '%')
            or aou.wechat_friend_id like concat('%', #{reqVo.friendWechatId}, '%')
            or cast(aou.id as char) = #{reqVo.friendWechatId}
            or cast(aou.bind_user_id as char) = #{reqVo.friendWechatId}
        )


        and aou.bind_user_id = #{reqVo.bindUserId}


        and (
            mu.nickname like concat('%', #{reqVo.nickname}, '%')
            or mu.mobile like concat('%', #{reqVo.nickname}, '%')
            or cast(mu.id as char) = #{reqVo.nickname}
        )


        and (
            km.name like concat('%', #{reqVo.kfName}, '%')
            or km.wechat_account_id like concat('%', #{reqVo.kfName}, '%')
            or km.code like concat('%', #{reqVo.kfName}, '%')
            or cast(km.id as char) = #{reqVo.kfName}
        )



        and aou.friend_alias = #{reqVo.friendAlias}


        and aou.friend_nickname = #{reqVo.friendNickname}


        AND date_format(aou.create_time, '%Y-%m-%d %H:%i:%s')  BETWEEN #{reqVo.startTime} AND #{reqVo.endTime}


order by aou.id desc
